shapes.code:
sealed interface Shape
data class Rectangle(val width: Int, val height: Int) : Shape
data class Triangle(val base: Int, val height: Int) : Shape

// `when` over a sealed type must be exhaustive; `is` smart-casts the subject.
fun area(shape: Shape): Int = when (shape) {
    is Rectangle -> shape.width * shape.height
    is Triangle -> shape.base * shape.height / 2
}

fun main() {
    println("Rectangle: ${area(Rectangle(3, 4))}")
    println("Triangle: ${area(Triangle(10, 3))}")
}

signature.code:
// Nullability is part of the type: String is never null, String? may be.
data class User(val name: String, val email: String?)

// An extension on a nullable receiver, using ?. (safe call) and ?: (elvis).
fun User?.domain(): String = this?.email?.substringAfter('@') ?: "(none)"

fun main() {
    val users: List<User?> = listOf(User("ada", "ada@example.org"), User("bob", null), null)
    for (u in users) println("${u?.name ?: "nobody"} -> ${u.domain()}")

    val email = users[0]?.email
    // println(email.length)                 // compile error: email is String?
    if (email != null) println(email.length)  // smart cast to String after the check

    println(users[0]?.copy(name = "lovelace"))  // data classes get copy() and toString()
}
